#!/usr/bin/env python3
"""Adds the sample plan page (/sample-plan/) and the line + link on the $29 offer.
New files: sample-plan/index.html, plan_sample_link.js. Edits: one script line in
index.html, one entry in sitemap.xml. Checks fingerprints first; changes nothing
unless everything matches. Undo: python3 sample_oct27.py --undo"""
import sys,os,json,base64,zlib,hashlib,shutil
C=json.loads('{"idx_old": "bb5925671b7cf7c93c050c3b51dd3bed30bab53db8083d590a4a3df1262e44be", "site_old": "bee6aa5ce3302a0f5346cf8c56979440e4c5eef2d15e42178668393c4c217ff8", "anchor": "<script src=\\"dream_college.js?v=20261020\\"></script>", "tag": "<script src=\\"plan_sample_link.js?v=20261027\\"></script>", "url": "  <url>\\n    <loc>https://freepracticesat.com/sample-plan/</loc>\\n    <lastmod>2026-10-27</lastmod>\\n  </url>\\n", "files": {"sample-plan/index.html": "", "plan_sample_link.js": ""}, "fsha": {"sample-plan/index.html": "09e2daae6ca8379bca65da2368cfa1d9afd114ae98189338dfcfbf539c33ba5c", "plan_sample_link.js": "730054abe1d952b6ae24d7b16067bcba6b7e429f3e6ca8ecf17959660ace9fa9"}}')
BK='.sample_backup_20261027'
sha=lambda b: hashlib.sha256(b).hexdigest()
rd=lambda p: open(p,'rb').read()
if '--undo' in sys.argv:
    if not os.path.isdir(BK): sys.exit('No backup found. Nothing undone.')
    for f in ('index.html','sitemap.xml'): shutil.copyfile(os.path.join(BK,f),f)
    for f in C['files']:
        if os.path.exists(f): os.rename(f,os.path.join(BK,'removed_'+f.replace('/','_')))
    print('UNDONE: index.html and sitemap.xml restored, new files moved into '+BK+'. Click Republish.'); sys.exit()
idx=rd('index.html'); site=rd('sitemap.xml')
done=C['tag'].encode() in idx
if done and all(os.path.exists(f) and sha(rd(f))==C['fsha'][f] for f in C['files']):
    print('Already done. Nothing to change.'); sys.exit()
bad=[]
if sha(idx)!=C['idx_old']: bad.append('index.html')
if sha(site)!=C['site_old']: bad.append('sitemap.xml')
if idx.count(C['anchor'].encode())!=1: bad.append('index.html (script line not found once)')
if site.count(b'</urlset>')!=1: bad.append('sitemap.xml (end tag)')
for f in C['files']:
    if os.path.exists(f): bad.append(f+' (already exists)')
if bad:
    print('STOP. Nothing was changed. These files differ from what was checked:'); print('\n'.join(bad)); sys.exit(1)
os.makedirs(BK,exist_ok=True)
shutil.copyfile('index.html',os.path.join(BK,'index.html')); shutil.copyfile('sitemap.xml',os.path.join(BK,'sitemap.xml'))
for f,d in C['files'].items():
    b=zlib.decompress(base64.b64decode(d)); assert sha(b)==C['fsha'][f]
    if os.path.dirname(f): os.makedirs(os.path.dirname(f),exist_ok=True)
    open(f,'wb').write(b)
a=C['anchor'].encode()
open('index.html','wb').write(idx.replace(a,a+b'\n'+C['tag'].encode()))
open('sitemap.xml','wb').write(site.replace(b'</urlset>',C['url'].encode()+b'</urlset>'))
print('DONE: sample plan page added and the $29 offer updated. Click Republish.')
